def format_bytes(n):
    """Format bytes into a human-readable size string."""
    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        return "0 B"

    units = ['B', 'KB', 'MB', 'GB', 'TB']
    unit_index = 0
    size = float(n)

    while size >= 1024 and unit_index < len(units) - 1:
        size /= 1024
        unit_index += 1

    return f"{size:.2f} {units[unit_index]}"
